-- Original offer criteria correct eligibility; no NPC spawn/graph/acceptance is inferred.
CREATE TABLE recurring_hunter_native_offers (
 definition_id integer NOT NULL, version integer NOT NULL,
 node_id integer NOT NULL CHECK(node_id>0), choice_id integer NOT NULL CHECK(choice_id>0),
 minimum_level integer NOT NULL CHECK(minimum_level>0), category_id integer NOT NULL CHECK(category_id>0),
 criterion text NOT NULL, source_authority text NOT NULL,
 PRIMARY KEY(definition_id,version), UNIQUE(version,node_id,choice_id),
 FOREIGN KEY(definition_id,version) REFERENCES recurring_hunter_contracts
);
CREATE TRIGGER recurring_hunter_native_offer_immutable BEFORE UPDATE OR DELETE ON recurring_hunter_native_offers
FOR EACH ROW EXECUTE FUNCTION recurring_hunter_immutable_source();
-- Acceptance-source table intentionally remains unseeded: a native choice offer is not a recovered server publisher.
